∀ {N : ℕ} {M : AbcAdaptation.Tripod.Fermat.Proper.Model N}
  (self : AbcAdaptation.Tripod.Fermat.Proper.AffineIdentification M)
  (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hv : M.v ∈ ↑(↑x).P), (↑(self.equiv x)).2 = (↑x).eval M.v hv

∀ {N : ℕ} {K : IntermediateField ℚ AbcAdaptation.Tripod.Fermat.Proper.Ω} {u v : ↥K}
  {transcendental_u : Transcendental ℚ u} {equation : u ^ N + v ^ N = 1} {generate : ℚ⟮u, v⟯ = ⊤}
  {finite_u : FiniteDimensional ↥ℚ⟮u⟯ ↥K} {degree_u : Module.finrank ↥ℚ⟮u⟯ ↥K = N}
  {K_1 : IntermediateField ℚ AbcAdaptation.Tripod.Fermat.Proper.Ω} {u_1 v_1 : ↥K_1}
  {transcendental_u_1 : Transcendental ℚ u_1} {equation_1 : u_1 ^ N + v_1 ^ N = 1} {generate_1 : ℚ⟮u_1, v_1⟯ = ⊤}
  {finite_u_1 : FiniteDimensional ↥ℚ⟮u_1⟯ ↥K_1} {degree_u_1 : Module.finrank ↥ℚ⟮u_1⟯ ↥K_1 = N},
  { K := K, u := u, v := v, transcendental_u := transcendental_u, equation := equation, generate := generate,
        finite_u := finite_u, degree_u := degree_u } =
      { K := K_1, u := u_1, v := v_1, transcendental_u := transcendental_u_1, equation := equation_1,
        generate := generate_1, finite_u := finite_u_1, degree_u := degree_u_1 } →
    K = K_1 ∧ u ≍ u_1 ∧ v ≍ v_1

∀ {K : Type u_1} {inst : Field K} {inst_1 : CharZero K} {P : AbcAdaptation.Tripod.Fermat.Proper.Place K}
  {σ : P.ResidueField →+* AbcAdaptation.Tripod.Qbar} {P_1 : AbcAdaptation.Tripod.Fermat.Proper.Place K}
  {σ_1 : P_1.ResidueField →+* AbcAdaptation.Tripod.Qbar},
  { P := P, σ := σ } = { P := P_1, σ := σ_1 } → P = P_1 ∧ σ ≍ σ_1

∀ {N : ℕ} {M : AbcAdaptation.Tripod.Fermat.Proper.Model N}
  {equiv : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M ≃ AbcAdaptation.Tripod.Fermat.Pt N}
  {eval_u :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hu : M.u ∈ ↑(↑x).P), (↑(equiv x)).1 = (↑x).eval M.u hu}
  {eval_v :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hv : M.v ∈ ↑(↑x).P), (↑(equiv x)).2 = (↑x).eval M.v hv}
  {field_eq :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M),
      (↑x).fieldOf = AbcAdaptation.Tripod.Fermat.fieldOf (equiv x)}
  {equiv_1 : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M ≃ AbcAdaptation.Tripod.Fermat.Pt N}
  {eval_u_1 :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hu : M.u ∈ ↑(↑x).P), (↑(equiv_1 x)).1 = (↑x).eval M.u hu}
  {eval_v_1 :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hv : M.v ∈ ↑(↑x).P), (↑(equiv_1 x)).2 = (↑x).eval M.v hv}
  {field_eq_1 :
    ∀ (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M),
      (↑x).fieldOf = AbcAdaptation.Tripod.Fermat.fieldOf (equiv_1 x)},
  { equiv := equiv, eval_u := eval_u, eval_v := eval_v, field_eq := field_eq } =
      { equiv := equiv_1, eval_u := eval_u_1, eval_v := eval_v_1, field_eq := field_eq_1 } →
    equiv = equiv_1

∀ {N : ℕ} {M : AbcAdaptation.Tripod.Fermat.Proper.Model N}
  (self : AbcAdaptation.Tripod.Fermat.Proper.AffineIdentification M)
  (x : AbcAdaptation.Tripod.Fermat.Proper.AffinePoint M) (hu : M.u ∈ ↑(↑x).P), (↑(self.equiv x)).1 = (↑x).eval M.u hu
